from django import template
from django.utils.html import escape
from django.utils.safestring import mark_safe

register = template.Library()


def format_html_attrs(attrs):
    attr_list = []
    for key, attr_value in attrs.items():
        attr_list.append(f'{key.replace("_", "-")}="{escape(str(attr_value))}"')
    return mark_safe(" ".join(attr_list))


@register.inclusion_tag('components/form_field.html')
def djinn_form_field(
    field=None,
    label_class="",
    class_name="",
    field_id="",
    **attrs
):
    """
    Djinn FormField component tag.

    Renders a Django BoundField with label, errors, and help text.

    Usage: {% djinn_form_field field=form.email label_class="mb-2" %}
    """
    if field is None:
        return {
            "field": None,
            "label_class": "",
            "class": "",
            "id": "",
            "attrs": "",
        }

    return {
        "field": field,
        "label_class": label_class,
        "class": class_name,
        "id": field_id or field.id_for_label,
        "attrs": format_html_attrs(attrs),
    }
